interface Entry {
  value: number;
  storedAt: number;
}

export class Cache {
  private store = new Map<string, Entry>();

  constructor(private capacity: number, private ttl: number) {}

  put(key: string, value: number, now: number): void {
    this.store.delete(key);
    if (this.store.size >= this.capacity) {
      const oldestKey = this.store.keys().next().value;
      if (oldestKey !== undefined) {
        this.store.delete(oldestKey);
      }
    }
    this.store.set(key, { value, storedAt: now });
  }

  get(key: string, now: number): number | undefined {
    const entry = this.store.get(key);
    if (entry === undefined) {
      return undefined;
    }
    if (now - entry.storedAt >= this.ttl) {
      this.store.delete(key);
      return undefined;
    }
    this.store.delete(key);
    this.store.set(key, entry);
    return entry.value;
  }
}

